<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Нужно ли ИП казначейское сопровождение?", "acceptedAnswer": {"@type": "Answer", "text": "Да, если ИП — исполнитель госконтракта, подпадающего под сопровождение, субподрядчик по такому контракту с авансом свыше 3 млн ₽ или получатель целевой субсидии либо гранта. Организационно-правовая форма роли не играет: режим распространяется на средства, а не на тип бизнеса."}}, {"@type": "Question", "name": "Какие документы нужны ИП для казначейского счёта?", "acceptedAnswer": {"@type": "Answer", "text": "Заявление в ГИИС «Электронный бюджет», документ-основание (контракт или соглашение), включение в Сводный реестр и квалифицированная электронная подпись ИП. Уставные документы и карточка образцов подписей не нужны, машиночитаемая доверенность — только для представителя."}}, {"@type": "Question", "name": "Может ли ИП работать по 44-ФЗ без казначейского счёта?", "acceptedAnswer": {"@type": "Answer", "text": "Да, если контракт не подпадает под казначейское сопровождение — а это большинство обычных закупок. Счёт 71 нужен только по сопровождаемым контрактам: пороги 2026 года — авансы от 100 млн ₽, единственный поставщик и гособоронзаказ свыше 3 млн ₽, субсидии без порога."}}, {"@type": "Question", "name": "Чем казначейское сопровождение для ИП отличается от ООО?", "acceptedAnswer": {"@type": "Answer", "text": "Содержательно ничем: те же счёт 71, сведения, санкционирование и раздельный учёт. Различия процедурные: ИП подписывает документы сам своей подписью, доверенности и уставные документы не требуются, а потолок штрафа за раздельный учёт ниже — 250 тыс. ₽ против 500 тыс. ₽ у юридических лиц."}}, {"@type": "Question", "name": "Открывает ли ИП лицевой счёт 71?", "acceptedAnswer": {"@type": "Answer", "text": "Да. ИП — неучастник бюджетного процесса, поэтому ему открывают именно лицевой счёт участника казначейского сопровождения с кодом 71 в территориальном органе Федерального казначейства; внутри счёта по каждому контракту заводится отдельный раздел."}}, {"@type": "Question", "name": "Нужна ли ИП машиночитаемая доверенность?", "acceptedAnswer": {"@type": "Answer", "text": "Как правило, нет. МЧД оформляется, когда документы подписывает не сам предприниматель, а его представитель личным сертификатом физического лица. Если ИП подписывает всё своей квалифицированной подписью — доверенность не нужна."}}, {"@type": "Question", "name": "Платит ли ИП налоги с казначейского счёта?", "acceptedAnswer": {"@type": "Answer", "text": "Платить налоги и взносы с лицевого счёта можно — это разрешённая операция, которая заявляется в сведениях и проходит санкционирование. Сам налоговый режим не меняется: доход по упрощённой системе признаётся на дату поступления средств на лицевой счёт."}}, {"@type": "Question", "name": "Сколько стоит казначейское сопровождение для ИП?", "acceptedAnswer": {"@type": "Answer", "text": "Государство за режим ничего не берёт: открытие и ведение лицевого счёта — без взимания платы. Расходы ИП — это подпись, время на документы и, при желании, услуги специалистов: открытие счёта под ключ — 29 000 ₽, контракт с постоплатой под ключ — 55 000 ₽ по фиксированным тарифам."}}, {"@type": "Question", "name": "Как быстро ИП откроют счёт в казначействе?", "acceptedAnswer": {"@type": "Answer", "text": "При корректном комплекте раздел по контракту открывается, как правило, не позднее следующего рабочего дня. Основное время занимает подготовка: выпуск подписи и включение в Сводный реестр, поэтому начинать стоит сразу после победы в закупке."}}, {"@type": "Question", "name": "Что грозит ИП за нарушение правил сопровождения?", "acceptedAnswer": {"@type": "Answer", "text": "Главный риск 2026 года — штраф за отсутствие раздельного учёта по ст. 15.37.1 КоАП: 5–10 % цены контракта, но не более 250 тыс. ₽, срок давности — три года. Плюс операционные последствия: возвраты распоряжений, задержки платежей, приостановление операций при нарушениях режима."}}, {"@type": "Question", "name": "ИП — субподрядчик у исполнителя госконтракта. Счёт тоже нужен?", "acceptedAnswer": {"@type": "Answer", "text": "Да, если по сопровождаемому контракту субподрядчику перечисляется аванс свыше 3 млн ₽ — режим спускается по цепочке кооперации, и счёт 71 открывает каждый её участник, получающий целевые средства."}}, {"@type": "Question", "name": "Можно ли перевести деньги с лицевого счёта себе на карту?", "acceptedAnswer": {"@type": "Answer", "text": "Просто так — нет: перечисление средств себе допускается в предусмотренных правилами случаях, например при возмещении фактически произведённых расходов с подтверждающими документами или при перечислении прибыли после исполнения обязательств по контракту."}}]}
</script>
<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "HowTo", "name": "Как ИП открыть казначейский счёт", "inLanguage": "ru-RU", "step": [{"@type": "HowToStep", "position": 1, "name": "Получить подпись ИП", "text": "Выпустить квалифицированную электронную подпись индивидуального предпринимателя в удостоверяющем центре ФНС и проверить вход в ГИИС «Электронный бюджет»."}, {"@type": "HowToStep", "position": 2, "name": "Проверить Сводный реестр", "text": "Убедиться, что ИП включён в Сводный реестр участников и неучастников бюджетного процесса; при отсутствии записи — инициировать включение через заказчика или территориальный орган казначейства."}, {"@type": "HowToStep", "position": 3, "name": "Сформировать заявление", "text": "В ГИИС «Электронный бюджет» создать заявление на открытие лицевого счёта участника казначейского сопровождения (код 71), приложить документ-основание — контракт или соглашение."}, {"@type": "HowToStep", "position": 4, "name": "Подписать и подать", "text": "Подписать заявление квалифицированной подписью ИП — машиночитаемая доверенность при личном подписании не нужна — и направить в свой территориальный орган казначейства."}, {"@type": "HowToStep", "position": 5, "name": "Дождаться открытия", "text": "При корректном комплекте раздел по контракту открывается, как правило, не позднее следующего рабочего дня; реквизиты счёта передать заказчику для перечисления средств."}, {"@type": "HowToStep", "position": 6, "name": "Настроить работу по счёту", "text": "До первого платежа подготовить сведения об операциях с целевыми средствами и раздельный учёт по контракту; платежи проводить распоряжениями с документами-основаниями."}]}
</script>
<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "DefinedTermSet", "name": "Термины: казначейское сопровождение для ИП", "inLanguage": "ru-RU", "hasDefinedTerm": [{"@type": "DefinedTerm", "name": "Казначейское сопровождение", "description": "Режим контроля целевых средств по главе 24.4 Бюджетного кодекса: средства зачисляются на лицевой счёт в казначействе, каждый платёж проходит санкционирование."}, {"@type": "DefinedTerm", "name": "Лицевой счёт с кодом 71", "description": "Единый лицевой счёт участника казначейского сопровождения, который территориальный орган казначейства открывает неучастникам бюджетного процесса — организациям и ИП."}, {"@type": "DefinedTerm", "name": "Неучастник бюджетного процесса", "description": "Юридическое лицо или ИП, не входящие в систему органов и учреждений бюджетной сферы; статус определяет тип лицевого счёта."}, {"@type": "DefinedTerm", "name": "Сводный реестр", "description": "Реестр участников и неучастников бюджетного процесса; включение в него — обязательное условие открытия лицевого счёта."}, {"@type": "DefinedTerm", "name": "Квалифицированная электронная подпись ИП", "description": "Подпись, выданная удостоверяющим центром ФНС на индивидуального предпринимателя; ею подписываются документы в ГИИС «Электронный бюджет»."}, {"@type": "DefinedTerm", "name": "Машиночитаемая доверенность (МЧД)", "description": "Электронная доверенность на представителя; самому ИП при личном подписании не требуется."}, {"@type": "DefinedTerm", "name": "Сведения об операциях с целевыми средствами", "description": "Плановый документ (форма 0501213) со структурой расходов по контракту; платежи проходят только в его рамках."}, {"@type": "DefinedTerm", "name": "Раздельный учёт", "description": "Обособленный учёт доходов и расходов по каждому сопровождаемому контракту; обязателен и для ИП независимо от налогового режима."}]}
</script>
